INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (137, 282, 'Golden tear tape', '../upload/image/20180929/20180929104236_18585.jpg', '<p></p><p style="text-align:left;color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="color:#E53333;font-family:Tahoma;font-size:16px;"><strong>Golden tear tape </strong></span></p> <p style="text-align:left;color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="color:#E53333;font-family:Tahoma;font-size:16px;">Type:</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:16px;">It was self adhesive tear tape. tear tape have BOPP tear tape, BOPET tear tape,cigarette tear tape,self adhesive tear tape,and other non cigarette usage tear tapes</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:16px;">Ordinary self adhesive tear tape</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:16px;">Laser self adhesive tear tape</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:16px;">Anti-counterfeiting self adhesive tear tape</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:16px;">Lace self adhesive tear tape</span></p> <p style="text-align:left;color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="color:#E53333;font-family:Tahoma;font-size:16px;">Certification: ISO9001, ISO14001, OHSMS18000</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:16px;">1)Various sizes for adhesive tear tape:</span><br/> <br/> <span style="color:#E53333;font-family:Tahoma;font-size:16px;">Thickness 25-40UM</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:16px;">Width 1.6mm-10.0mm</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:16px;">Length 5,000m-70,000m</span><br/> <br/> <span style="color:#E53333;font-family:Tahoma;font-size:16px;">2) Printing design:</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:16px;">a) Color printing of tear tape rolls: gold, single gold, single silver, full solid red, yellow,white,black, etc.</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:16px;">b) Logo printing of tear tape rolls: ink printing logo, laser, holographic effect</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:16px;">3.) Packing for of tear tape rolls: Cartons (16rolls/carton)</span><br/> <br/> <span style="color:#E53333;font-family:Tahoma;font-size:16px;">Application area:</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:16px;"> packing/opening of cigarette packs and other packs.</span></p> <p style="text-align:left;color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="color:#E53333;font-family:Tahoma;font-size:16px;">Our Services</span><br/> <br/> <span style="color:#E53333;font-family:Tahoma;font-size:16px;">1) Factory direct sale.</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:16px;">2.)The color and the design can be customized</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:16px;">3.) provide free samples to customers test.</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:16px;">4) 10 years experience</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:16px;">5) Fast , accurate quotes.</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:16px;">6.)Our good service.</span><br/> <br/></p>', '2026-09-06 20:58:45');